import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const OUT = process.env.CLAUDE_JOB_DIR + '/tmp/shots';
const browser = await chromium.launch();
for (const [name, w, h] of [['desktop',1440,900],['tablet',1023,900],['mobile',402,900]]) {
  const page = await browser.newPage({ viewport:{width:w,height:h}, deviceScaleFactor:1 });
  await page.goto('http://localhost:3000/', { waitUntil:'networkidle', timeout:60000 });
  await page.waitForSelector('footer[role="contentinfo"]', { timeout:30000 });
  const data = await page.evaluate(() => {
    const q = (sel) => { const el = document.querySelector(sel); if(!el) return null;
      const r = el.getBoundingClientRect(); const cs = getComputedStyle(el);
      return {w:Math.round(r.width), h:Math.round(r.height), x:Math.round(r.x),
              display:cs.display, flexDir:cs.flexDirection, gap:cs.gap, pad:cs.padding, mw:cs.maxWidth, flex:cs.flex}; };
    const f = document.querySelector('footer[role="contentinfo"]');
    const fr = f.getBoundingClientRect();
    const cols = [...f.querySelectorAll('ul')].map(u=>{const p=u.parentElement.getBoundingClientRect();return {x:Math.round(p.x),w:Math.round(p.width),h:Math.round(p.height)};});
    const icons = [...f.querySelectorAll('svg[role="img"][aria-label]')].filter(s=>s.getAttribute('aria-label')!=='Zimmermann')
      .map(s=>{const r=s.getBoundingClientRect();return {label:s.getAttribute('aria-label'),x:Math.round(r.x),y:Math.round(r.y)};});
    const logo = f.querySelector('svg[aria-label="Zimmermann"]');
    return { footer:{w:Math.round(fr.width),h:Math.round(fr.height)},
      contentRow:q('footer[role=contentinfo] > div > div'),
      cols, icons,
      logo: logo? (()=>{const r=logo.getBoundingClientRect();return{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}})() : null,
      bottomBarH: (()=>{const b=f.lastElementChild.getBoundingClientRect();return Math.round(b.height)})(),
    };
  });
  console.log('\n########## '+name+' ('+w+'px) ##########');
  console.log(JSON.stringify(data,null,1));
  await page.locator('footer[role="contentinfo"]').screenshot({ path:`${OUT}/${name}.png` });
  await page.close();
}
await browser.close();
EOF
