import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
const p = await b.newPage({ viewport:{width:1440,height:900} });
await p.goto('http://localhost:3000/', { waitUntil:'domcontentloaded', timeout:60000 });
await p.waitForSelector('footer[role="contentinfo"]');
const r = await p.evaluate(() => {
  const f=document.querySelector('footer[role=contentinfo]');
  const contact=[...f.querySelectorAll('ul')].map(u=>u.parentElement).find(c=>/contact/i.test(c.querySelector('p')?.textContent||''));
  const li=contact.querySelector('li'), a=li.querySelector('a'), ul=contact.querySelector('ul'), row=ul.nextElementSibling;
  const cs=e=>getComputedStyle(e);
  const out={
    diag:{ liDisplay:cs(li).display, liHeight:Math.round(li.getBoundingClientRect().height),
           aDisplay:cs(a).display, aHeight:Math.round(a.getBoundingClientRect().height),
           colGap:cs(contact).gap, ulGap:cs(ul).gap, liPadLeft:cs(li).paddingLeft, rowPadTop:cs(row).paddingTop },
  };
  const measure=()=>{const base=contact.getBoundingClientRect();
    const items=[...contact.querySelectorAll('li a')].map(e=>{const x=e.getBoundingClientRect();return {x:+(x.x-base.x).toFixed(1),y:+(x.y-base.y).toFixed(1)};});
    const ic=contact.querySelector('div[class] span');
    const icb=ic.getBoundingClientRect();
    return {items, icon:{x:+(icb.x-base.x).toFixed(1), y:+(icb.y-base.y).toFixed(1)}};};
  out.before=measure();
  // FIX C: li display flex (kill the 2px inline descender gap)
  [...contact.querySelectorAll('li')].forEach(l=>{l.style.display='flex';});
  out.afterC=measure();
  // FIX B: drop the 4px inset on Contact items
  [...contact.querySelectorAll('li')].forEach(l=>{l.style.paddingLeft='0';});
  out.afterBC=measure();
  // FIX A: heading owns the 16px, column gap 0 -> icon row sits flush after the ul
  contact.style.gap='0'; contact.querySelector('p').style.marginBottom='16px';
  out.afterABC=measure();
  return out;
});
console.log('DIAGNOSTIC:', JSON.stringify(r.diag));
console.log('\nstage      item1 x,y      item3 x,y      icon x,y');
const row=(t,m)=>console.log(t.padEnd(11), JSON.stringify(m.items[0]).padEnd(15), JSON.stringify(m.items[2]).padEnd(15), JSON.stringify(m.icon));
row('before',r.before); row('+C',r.afterC); row('+C+B',r.afterBC); row('+C+B+A',r.afterABC);
console.log('\nFIGMA        {"x":0,"y":24}   {"x":0,"y":72}   {"x":0,"y":96}');
await b.close();
EOF
