import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
const p = await b.newPage({ viewport:{width:1440,height:900} });
await p.goto('http://localhost:3000/', { waitUntil:'domcontentloaded', timeout:60000 });
await p.waitForSelector('footer[role="contentinfo"]');
const r = await p.evaluate(() => {
  const f=document.querySelector('footer[role=contentinfo]');
  const contact=[...f.querySelectorAll('ul')].map(u=>u.parentElement).find(c=>/contact/i.test(c.querySelector('p')?.textContent||''));
  const ul=contact.querySelector('ul');
  const row=[...contact.children].find(c=>c.tagName==='DIV');       // the real contactRow
  const heading=contact.querySelector('p');
  const m=()=>{const base=contact.getBoundingClientRect();
    const rel=e=>{const x=e.getBoundingClientRect();return {x:+(x.x-base.x).toFixed(1),y:+(x.y-base.y).toFixed(1)};};
    const items=[...contact.querySelectorAll('li a')].map(rel);
    const icon=rel(row.querySelector('span'));
    return {i1:items[0], i3:items[2], icon};};
  const out={ rowPadTop:getComputedStyle(row).paddingTop, rowClass:row.className, before:m() };
  [...contact.querySelectorAll('li')].forEach(l=>{l.style.display='flex';});                 // C
  out.C=m();
  [...contact.querySelectorAll('li')].forEach(l=>{l.style.paddingLeft='0';});                  // B
  out.CB=m();
  contact.style.gap='0'; heading.style.marginBottom='16px';                                    // A
  out.CBA=m();
  return out;
});
console.log('contactRow class:', r.rowClass, '| padding-top:', r.rowPadTop, '\n');
console.log('stage     item1          item3          icon');
for (const k of ['before','C','CB','CBA']) console.log(k.padEnd(9), JSON.stringify(r[k].i1).padEnd(14), JSON.stringify(r[k].i3).padEnd(14), JSON.stringify(r[k].icon));
console.log('\nFIGMA     {"x":0,"y":24} {"x":0,"y":72} {"x":0,"y":96}');
await b.close();
EOF
