import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent('<body></body>');
const r = await p.evaluate(() => {
  const STR='BOOK AN APPOINTMENT';
  const measure = (fam) => {
    const s=document.createElement('span');
    s.style.cssText=`position:absolute;white-space:nowrap;font-size:12px;font-weight:500;letter-spacing:0;text-transform:uppercase;font-family:${fam}`;
    s.textContent=STR; document.body.appendChild(s);
    const w=s.getBoundingClientRect().width; s.remove(); return Math.round(w*10)/10;
  };
  const stack = "'Futura Round','Futura LT Pro','Futura','Century Gothic','Gill Sans','Trebuchet MS',Arial,sans-serif";
  const out={ fullStack: measure(stack) };
  for (const f of ['Futura Round','Futura LT Pro','Futura','Century Gothic','Gill Sans','Trebuchet MS','Arial','sans-serif','monospace']) {
    out[f]=measure(`'${f}'`);
  }
  // which named fonts does the platform actually have?
  out._available={};
  for (const f of ['Futura Round','Futura LT Pro','Futura','Century Gothic','Gill Sans','Trebuchet MS','Arial'])
    out._available[f]=document.fonts.check(`12px '${f}'`);
  return out;
});
console.log(JSON.stringify(r,null,1));
await b.close();
EOF
